'use strict';

/*::
import type {
  AutolinkedDep,
  AutolinkingIosPlatform,
  PodspecModel,
  ScaffoldResult,
  SpmScaffoldSpec,
} from './spm-types';
*/

/**
 * scaffold-package-swift.js — generates a `Package.swift` into
 * `node_modules/<dep>/` for community RN libraries that don't ship SPM
 * support. The autolinker's existing `isSelfManagedPackage` check
 * (generate-spm-autolinking.js, AUTOGEN_MARKER) treats these scaffolded
 * files as self-managed and references them directly from the aggregator —
 * no autolinker changes required.
 *
 * Three layers:
 *   - translatePodspecToSpmTarget(model, dep): pure translation
 *   - emitScaffoldedPackageSwift(spec, ctx): pure Swift emission
 *   - scaffoldPackageSwiftForDep(dep, ctx): I/O + skip-rule + write
 *   - scaffoldAll(opts): orchestrator over autolinking.json
 */

const {
  SpmNameCollisionError,
  defaultReadConfig,
  defaultReadPodspec,
  defaultResolveDep,
  expandSpmDependencies,
  resolveSwiftName,
} = require('./expand-spm-dependencies');
const {expandSpmSourceGlobs} = require('./generate-spm-autolinking');
const {MIN_IOS_VERSION_SUPPORTED} = require('./ios-deployment-target');
const {findPodspecs, readPodspecCached} = require('./read-podspec');
const {
  REACT_CODEGEN_PACKAGE_NAME,
  REACT_CODEGEN_PRODUCTS,
  REACT_NATIVE_PACKAGE_NAME,
  REACT_NATIVE_PRODUCTS,
  SCAFFOLDER_MARKER,
  makeLogger,
  remotePackageConfig,
  toC99Name,
} = require('./spm-utils');
const {readSwiftpmConfig, writeSwiftpmName} = require('./swiftpm-config');
const fs = require('node:fs');
const path = require('node:path');

const {log, warn} = makeLogger('scaffold-package-swift');

// SCAFFOLDER_MARKER lives in spm-utils.js (shared, no import cycle). It must NOT
// contain the autolinker's AUTOGEN_MARKER ('// AUTO-GENERATED by
// scripts/generate-spm-autolinking.js') — that marker is what the autolinker
// uses to tell self-managed deps from its own synth output. Our marker is
// recognized by the scaffolder itself (skip-rule), but invisible to the
// autolinker (treated as self-managed).

// Bump when the emitter's output format changes in a way that requires
// re-scaffolding existing files (rather than just being a content drift the
// cache-slot label already handles). v2: swift-tools-version moved to
// line 1 — pre-v2 scaffolds emit it on a later line, which recent Xcode
// rejects with "Swift tools version 3.1.0 ... no longer supported". v4: the
// single `let rnHeaders = appRoot + "/.../ReactHeadersAll"` split into the two
// `rnCoreHeaders` / `appHeaders` lets (merged tree replaced by two trees), so
// pre-v4 scaffolds reference a tree that is no longer materialized. v5:
// header resolution moved to product dependencies (ReactNativeHeaders +
// ReactAppHeaders binary/headers targets) — the rnCoreHeaders/appHeaders
// trees no longer exist, so pre-v5 scaffolds carry dead lets and would break
// if anything still referenced them. v7: the runtime appRoot walker and the
// siblingPath helper are gone — package paths are plain relative strings
// computed at scaffold time (the walker anchored on
// build/xcframeworks/Package.swift, which remote mode no longer writes).
//
// Skip-rule contract: when an existing file's version is < this constant,
// the scaffolder regenerates regardless of --force (the bump implies the
// existing file is broken under current tooling). A file with the marker
// but no version line is treated as v1.
// v8: relative app paths (codegen / xcframeworks) are now computed from the
// autolinker's libs/<SwiftName> symlink location instead of the real dep.root,
// fixing a doubled-path resolution failure on fresh SwiftPM resolves.
// v9: header search paths derived from each subspec's header_mappings_dir
// (dirname) so namespaced includes (`<reanimated/...>`) resolve. v10:
// publicHeadersPath derived from the header_mappings_dir namespace root so a
// package exposes `<namespace/...>` to dependents; pod-style sibling deps
// (reanimated's `s.dependency "RNWorklets"`) wired to their npm package. v11:
// sibling .package path uses the libs/<SwiftName> symlink name, not the npm
// name (fixes "package ... doesn't exist" on resolve). v12: preprocessor
// defines from pod_target_xcconfig emitted as `.define(...)`. v13: ObjC(++)
// targets get an ambient-import prefix header (Foundation/UIKit) `-include`d,
// replacing CocoaPods' generated prefix.pch. v18: React-core deps also get
// the ReactNativeDependenciesHeaders product (ReactNativeHeaders went
// pure-RN; folly/glog/boost/... now come from the deps sidecar);
// publicHeadersPath falls back to "." for root-level-source podspecs
// (`s.source_files = "*.{h,m,mm}"`) instead of SPM's nonexistent `include/`.
// v19: scaffolded C++ targets carry DEBUG/NDEBUG config defines so their Fabric
// ABI matches the prebuilt React.framework (Release strips DebugStringConvertible
// under NDEBUG). Bumped so existing scaffolds regenerate with the defines.
// v20: the platform floor is the app's iOS deployment target in string form
// (the `.v15` enum cannot express a dependency minimum like 16.4).
const SCAFFOLDER_VERSION = 20;
const SCAFFOLDER_VERSION_LINE_RE = /^\/\/ AUTO-SCAFFOLDED-VERSION: (\d+)$/m;

// rn-xtool's own revision of this patched scaffolder, independent of
// upstream's SCAFFOLDER_VERSION. A scaffold without the marker (emitted by an
// older revision) or with a lower number is regenerated.
const RN_XTOOL_SCAFFOLD_REVISION = 1;
const RN_XTOOL_SCAFFOLD_REVISION_RE = /^\/\/ rn-xtool-scaffold-revision: (\d+)$/m;

// CocoaPods pods (not React Native / Expo modules, not autolinked siblings) whose
// SwiftPM package is known: a podspec `s.dependency "<pod>"` becomes
// `.package(url:exact:)` + `.product(name:package:)`. `exact` is the newest tag
// the podspecs seen here accept (`~> 1.0` → newest 1.x), pinned for reproducible
// builds: the generated `ios-xtool/` has no committed Package.resolved, so a
// range would drift between clean builds. The package identity SwiftPM derives is the URL's last path component.
// react-native-pager-view 9.x: `s.dependency "SwiftUIIntrospect", '~> 1.0'`.
const KNOWN_POD_SPM_PACKAGES /*: {[pod: string]: {url: string, exact: string, product: string}} */ = {
  SwiftUIIntrospect: {
    url: 'https://github.com/siteline/swiftui-introspect',
    exact: '1.5.0',
    product: 'SwiftUIIntrospect',
  },
};

// Pods that belong to Expo's own SwiftPM graph, never a CocoaPods-only pod.
function isExpoModuleDep(depName /*: string */) /*: boolean */ {
  return /^(expo-|Expo[A-Z]|EX[A-Z])/.test(depName);
}

function spmPackageIdentity(url /*: string */) /*: string */ {
  return path.basename(url).replace(/\.git$/, '').toLowerCase();
}

const AUTOGEN_MARKER =
  '// AUTO-GENERATED by scripts/generate-spm-autolinking.js';

// CocoaPods auto-generates a `<Target>-prefix.pch` that imports Foundation +
// UIKit into every ObjC translation unit, so pod sources can use NSThread /
// dispatch / UIKit symbols without an explicit import. SPM has no prefix-header
// mechanism, so we emit this file at the dep root and `-include` it on the
// target (cSettings + cxxSettings) to reproduce that ambient import. The
// `__OBJC__` guard makes it inert for plain C/C++ sources, and UIKit is
// `__has_include`-guarded for platforms that lack it.
// The config-gated C++ defines the prebuilt React.framework is built with (see
// packages/react-native/Package.swift). Fabric C++ in autolinked deps must
// compile with the SAME NDEBUG state or its DebugStringConvertible / ShadowNode
// ABI diverges from the Release React.framework and the link fails.
const REACT_CXX_CONFIG_DEFINES = [
  '.define("DEBUG", .when(configuration: .debug))',
  '.define("NDEBUG", .when(configuration: .release))',
];

const SCAFFOLD_PREFIX_HEADER = 'react-native-spm-prefix.h';
const SCAFFOLD_PREFIX_HEADER_CONTENTS = `// AUTO-SCAFFOLDED by react-native spm scaffold — mirrors CocoaPods' default
// prefix header so ObjC sources that rely on an implicit Foundation/UIKit
// import compile under SPM (which has no prefix-header mechanism). Safe to
// delete + regenerate via \`npx react-native spm scaffold\`.
#ifdef __OBJC__
#import <Foundation/Foundation.h>
#if __has_include(<UIKit/UIKit.h>)
#import <UIKit/UIKit.h>
#endif
#endif
`;

// Mixed-language libraries (Swift + C-family sources in one pod). CocoaPods
// and Xcode compile them as ONE module: Swift sees the pod's ObjC through the
// umbrella header, and ObjC sees Swift through the generated
// `<Module>-Swift.h`. SwiftPM >= 6.4 can build such a target behind the
// `experimentalMultiLang` tools-version feature (only with the swiftbuild
// backend; SE-0541 makes it standard, with no flag, in tools-version 6.5), but
// 6.4.x wires neither direction, so the manifest supplies both:
//   - Swift -> ObjC: `-import-objc-header <rn-spm-swift/umbrella.h>`, a
//     generated header importing Foundation/UIKit and the module's headers
//     except the C++ ones (or the podspec's own SWIFT_OBJC_BRIDGING_HEADER).
//   - ObjC -> Swift: `-I` the directory where Swift Build writes
//     `<Module>-Swift.h` (`<scratch>/out/Intermediates.noindex/
//     GeneratedModuleMaps-<platform>`). It depends on the ROOT build's scratch
//     path, so it is read from RN_SPM_SWIFT_HEADERS_DIR when the manifest is
//     evaluated: a persisted (patch-package) manifest holds no absolute path.
//     Unset, it falls back to this package's own `.build`, which is only right
//     when the package is built on its own.
// Upstream candidate: replaces the former "mixed Swift/ObjC → skipped" gate.
const MIXED_TOOLS_VERSION_LINE =
  '// swift-tools-version: 6.4;(experimentalMultiLang)';
// SE-0541 makes mixed-language targets standard in tools-version 6.5, where the
// experimental flag is not read. A mixed target also gets this versioned
// manifest, otherwise identical: SwiftPM 6.5+ picks it, older ones ignore it.
const MIXED_MANIFEST_6_5 = 'Package@swift-6.5.swift';
const MIXED_TOOLS_VERSION_LINE_6_5 = '// swift-tools-version: 6.5';
const SWIFT_HEADERS_DIR_ENV = 'RN_SPM_SWIFT_HEADERS_DIR';
const SWIFT_HEADERS_FALLBACK =
  '.build/out/Intermediates.noindex/GeneratedModuleMaps-iphoneos';
// Generated support files for the mixed target (umbrella + -Swift.h shims).
// Kept out of `include/` so they never become part of the public module.
const MIXED_SUPPORT_DIR = 'rn-spm-swift';
const MIXED_UMBRELLA_HEADER = 'umbrella.h';
const isSwiftSource = (f /*: string */) /*: boolean */ => /\.swift$/i.test(f);
const isClangSource = (f /*: string */) /*: boolean */ =>
  /\.(mm?|c|cc|cpp|cxx)$/i.test(f);

// Include roots that hold C++-only code: an unresolved `#include <react/...>`
// (Fabric), `<folly/...>`, ... still marks the including header as C++.
const CXX_INCLUDE_PREFIXES = [
  'react/',
  'folly/',
  'jsi/',
  'jsireact/',
  'cxxreact/',
  'ReactCommon/',
  'yoga/',
  'glog/',
  'boost/',
  'fmt/',
  'double-conversion/',
  'hermes/',
];
const INCLUDE_RE = /^\s*#\s*(?:import|include)\s*([<"])([^>"]+)[>"]/gm;
const CXX_MARKER_RE =
  /\bnamespace\s+[\w:]*\s*\{|\btemplate\s*<|\bstd::|\busing\s+namespace\b|^\s*class\s+\w+\s*[:{]|^\s*#\s*include\s*<[a-z_]+>/m;

// Drops `#if(def) __cplusplus` branches (keeping their `#else`), which a
// Swift / Objective-C reader never sees.
function stripCplusplusBlocks(text /*: string */) /*: string */ {
  const out /*: Array<string> */ = [];
  // One entry per open #if: 'skip' while inside a __cplusplus branch.
  const stack /*: Array<'keep' | 'skip' | 'else'> */ = [];
  const skipping = () => stack.includes('skip');
  for (const line of text.split('\n')) {
    const t = line.trim();
    if (/^#\s*if/.test(t)) {
      stack.push(
        /^#\s*if(?:def\s+__cplusplus\b|\s+defined\s*\(?\s*__cplusplus\b|\s+__cplusplus\b)/.test(
          t,
        )
          ? 'skip'
          : 'keep',
      );
      continue;
    }
    if (/^#\s*(?:else|elif)\b/.test(t) && stack.length > 0) {
      if (stack[stack.length - 1] === 'skip') stack[stack.length - 1] = 'else';
      continue;
    }
    if (/^#\s*endif\b/.test(t)) {
      stack.pop();
      continue;
    }
    if (!skipping()) out.push(line);
  }
  return out.join('\n');
}

// The module headers Swift can import: CocoaPods' umbrella holds every public
// header, but a Swift-side bridging header is parsed as Objective-C, so a
// header that (transitively) pulls in C++ — typically a Fabric component view
// including RCTViewComponentView.h → <react/renderer/...> — is left out. Header
// lookups follow the module's own header dirs and `includeRoots` (the React
// header trees, when known); an unresolved include counts as C++ only when it
// names a C++-only root (CXX_INCLUDE_PREFIXES).
function swiftImportableHeaders(
  depRoot /*: string */,
  headers /*: Array<string> */,
  headerSearchPaths /*: Array<string> */,
  includeRoots /*: Array<string> */,
) /*: {safe: Array<string>, cxx: Array<string>} */ {
  const localRoots = headerSearchPaths.map(p => path.join(depRoot, p));
  const memo /*: Map<string, boolean> */ = new Map();
  const isCxx = (abs /*: string */) /*: boolean */ => {
    const known = memo.get(abs);
    if (known != null) return known;
    memo.set(abs, false); // cycle guard
    let text = '';
    try {
      text = stripCplusplusBlocks(fs.readFileSync(abs, 'utf8'));
    } catch {
      return false;
    }
    let tainted = /\.(hh|hpp|hxx)$/i.test(abs) || CXX_MARKER_RE.test(text);
    for (const m of tainted ? [] : text.matchAll(INCLUDE_RE)) {
      const [, delim, inc] = m;
      const candidates = [
        ...(delim === '"' ? [path.join(path.dirname(abs), inc)] : []),
        ...localRoots.map(r => path.join(r, inc)),
        ...includeRoots.map(r => path.join(r, inc)),
      ];
      const found = candidates.find(c => fs.existsSync(c));
      if (found != null ? isCxx(found) : CXX_INCLUDE_PREFIXES.some(p => inc.startsWith(p))) {
        tainted = true;
        break;
      }
    }
    memo.set(abs, tainted);
    return tainted;
  };
  const safe /*: Array<string> */ = [];
  const cxx /*: Array<string> */ = [];
  for (const h of headers) {
    (isCxx(path.join(depRoot, h)) ? cxx : safe).push(h);
  }
  return {safe, cxx};
}

// CocoaPods' header map also resolves a bare `#import "RCTFoo.h"` against the
// PUBLIC headers of the pod's dependencies — create-react-native-library's
// Fabric template writes `#import "RCTFabricComponentsPlugins.h"`, a React
// header. SwiftPM only exposes `<React/RCTFoo.h>`, so bare includes that match
// no local header but a React one get a forwarding stub here.
const REACT_BARE_HEADERS_DIR = 'rn-spm-react-headers';

function bareReactHeaders(
  depRoot /*: string */,
  files /*: Array<string> */,
  headerSearchPaths /*: Array<string> */,
  includeRoots /*: Array<string> */,
) /*: Array<string> */ {
  if (includeRoots.length === 0) return [];
  const localDirs = headerSearchPaths.map(p => path.join(depRoot, p));
  const found /*: Set<string> */ = new Set();
  for (const f of files) {
    let text = '';
    try {
      text = fs.readFileSync(path.join(depRoot, f), 'utf8');
    } catch {
      continue;
    }
    for (const m of text.matchAll(INCLUDE_RE)) {
      const [, delim, inc] = m;
      if (delim !== '"' || inc.includes('/') || found.has(inc)) continue;
      const local = [path.dirname(path.join(depRoot, f)), ...localDirs].some(d =>
        fs.existsSync(path.join(d, inc)),
      );
      if (
        !local &&
        includeRoots.some(r => fs.existsSync(path.join(r, 'React', inc)))
      ) {
        found.add(inc);
      }
    }
  }
  return [...found].sort();
}

// A podspec's own Swift bridging header (pod_target_xcconfig
// SWIFT_OBJC_BRIDGING_HEADER), dep-root relative. `undefined` when the podspec
// sets none, null when it sets one we cannot resolve.
function podspecBridgingHeader(
  podspecText /*: string */,
) /*: void | null | string */ {
  const m = podspecText.match(
    /SWIFT_OBJC_BRIDGING_HEADER['"]?\s*(?:=>|=|:)\s*['"]([^'"]+)['"]/,
  );
  if (m == null) {
    return undefined;
  }
  const rel = m[1]
    .replace(/\$[({]PODS_TARGET_SRCROOT[)}]\/?/g, '')
    .replace(/^\.\//, '');
  return /\$[({]|#\{/.test(rel) || path.posix.isAbsolute(rel) ? null : rel;
}

// Names of deps the scaffolder always refuses to touch — `react-native`
// itself is handled by the xcframework subpackage, never as an autolinked
// target.
const NEVER_SCAFFOLD /*: ReadonlySet<string> */ = new Set(['react-native']);

// React-core / React-Fabric / etc. dependency names collapse to a single
// invariant React header-product set. The app target links the prebuilt
// runtime frameworks outside SwiftPM. This
// list matches what `install_modules_dependencies(s)` materializes plus
// common podspec hand-rolled additions.
const REACT_CORE_DEP_PREFIXES = [
  'React-',
  'React_',
  'ReactCommon',
  'RCT-Folly',
  'RCT',
  'glog',
  'boost',
  'fmt',
  'DoubleConversion',
  'Yoga',
  'hermes-engine',
  'ReactAppDependencyProvider',
];

// Core pods whose name has no separator to match by prefix (`React-` etc.).
const REACT_CORE_DEP_EXACT = ['React'];

function isReactCoreDep(name /*: string */) /*: boolean */ {
  return (
    REACT_CORE_DEP_EXACT.includes(name) ||
    REACT_CORE_DEP_PREFIXES.some(p => name.startsWith(p))
  );
}

// True when the dep ships a `codegenConfig` in package.json — RN's standard
// marker that the library participates in the New Architecture / codegen. Such
// a lib's Fabric sources include the app-generated component headers
// (`<react/renderer/components/<name>/ShadowNodes.h>` etc.), which are vended by
// the per-app React-GeneratedCode package — so it implicitly depends on React
// core even when its podspec only wires that via `install_modules_dependencies`
// (which we strip). Safe/quiet: a missing or unparseable package.json → false.
function depHasCodegenConfig(depRoot /*: string */) /*: boolean */ {
  try {
    const pkg = JSON.parse(
      fs.readFileSync(path.join(depRoot, 'package.json'), 'utf8'),
    );
    return pkg != null && pkg.codegenConfig != null;
  } catch {
    return false;
  }
}

// Every subdirectory (relative to depRoot) under depRoot/base, recursively —
// used to expand a CocoaPods `path/**` recursive header search path into the
// concrete dirs SPM needs (SPM has no recursive search-path syntax). Skips
// VCS / build / dependency noise.
function collectSubdirs(
  depRoot /*: string */,
  base /*: string */,
) /*: Array<string> */ {
  const SKIP /*: Set<string> */ = new Set([
    'node_modules',
    'Pods',
    'build',
    '.git',
  ]);
  const out /*: Array<string> */ = [];
  const walk = (absDir /*: string */, relDir /*: string */) => {
    let entries /*: Array<{name: string, isDirectory(): boolean}> */ = [];
    try {
      // $FlowFixMe[incompatible-type] Dirent typing
      entries = fs.readdirSync(absDir, {withFileTypes: true});
    } catch {
      return;
    }
    for (const e of entries) {
      // $FlowFixMe[incompatible-type] Dirent.name is string|Buffer in stubs
      const name /*: string */ = e.name;
      if (!e.isDirectory() || name.startsWith('.') || SKIP.has(name)) continue;
      const rel = relDir === '.' ? name : `${relDir}/${name}`;
      out.push(rel);
      walk(path.join(absDir, name), rel);
    }
  };
  walk(path.join(depRoot, base), base === '.' ? '.' : base);
  return out;
}

// ---------------------------------------------------------------------------
// Translation
// ---------------------------------------------------------------------------

/**
 * Pure: turns a flattened PodspecModel into an SpmScaffoldSpec the emitter
 * can consume. Substitutes Xcode build-setting tokens (`$(PODS_TARGET_SRCROOT)`)
 * against the dep root, buckets dependencies, drops unknown tokens with a
 * warning.
 */
function translatePodspecToSpmTarget(
  model /*: PodspecModel */,
  dep /*: AutolinkedDep */,
  // Maps a podspec name (e.g. "RNWorklets") to the npm package name of an
  // autolinked sibling (e.g. "react-native-worklets"). Lets us wire a
  // `s.dependency "RNWorklets"` — a pod-style name the `react-native-*`
  // heuristic can't recognize — to the right sibling package. Empty by default.
  podToNpm /*: Map<string, string> */ = new Map(),
  // npm name → resolved Swift name for every autolinked dep, so a sibling
  // reference honors that sibling's `spm.name` instead of re-deriving it.
  swiftNameByNpm /*: Map<string, string> */ = new Map(),
  // Directories that resolve the dependencies' `<React/X.h>`-style includes
  // (the React header trees), used to keep C++ headers out of the Swift
  // umbrella of a mixed-language target. Empty: unknown.
  includeRoots /*: Array<string> */ = [],
) /*: SpmScaffoldSpec */ {
  const warnings = [...model.warnings];

  // Whatever the autolinker resolved (see resolveSwiftName). It registers the
  // dep under that name in its aggregator and in any sibling spm.dependencies
  // refs, so the scaffolded product/library name must match it exactly —
  // otherwise SPM fails to resolve `.product(name: "X", package: "X")`.
  const swiftName = dep.swiftName;
  if (swiftName == null) {
    throw new Error(
      `react-native spm scaffold: no resolved Swift name for '${dep.name}'. expandSpmDependencies must resolve every dep's name before a manifest is written.`,
    );
  }

  // Header search paths — substitute Xcode build-setting tokens against the
  // dep root. Anything we can't substitute is dropped + warned (avoids
  // emitting `$(SOMETHING)` literally into the Swift file).
  const headerSearchPaths /*: Array<string> */ = [];
  const addSearchPath = (p /*: string */) => {
    if (p.length > 0 && !headerSearchPaths.includes(p)) {
      headerSearchPaths.push(p);
    }
  };
  for (const raw of model.headerSearchPaths) {
    let substituted = raw
      .replace(/\$\(PODS_TARGET_SRCROOT\)/g, '.')
      .replace(/\$\{PODS_TARGET_SRCROOT\}/g, '.');
    if (/\$[({]/.test(substituted)) {
      warnings.push(
        `Dropped HEADER_SEARCH_PATHS entry "${raw}" — contains unresolved Xcode token. ` +
          `Add it manually if needed.`,
      );
      continue;
    }
    // CocoaPods `path/**` (or `/*`) = recursive search. SPM has no recursive
    // search-path syntax, so add the base dir + every subdirectory under it.
    const recursive = /\/\*\*?$/.test(substituted);
    substituted = substituted
      .replace(/\/\*\*?$/, '') // strip the glob marker
      .replace(/\/{2,}/g, '/'); // collapse `cpp//` → `cpp/`
    // Strip leading "./" (emitter prefixes with the target path) + trailing "/".
    const base = substituted
      .replace(/^\.\//, '')
      .replace(/^\//, '')
      .replace(/\/$/, '');
    addSearchPath(base === '' ? '.' : base);
    if (recursive) {
      for (const sub of collectSubdirs(dep.root, base === '' ? '.' : base)) {
        addSearchPath(sub);
      }
    }
  }

  // header_mappings_dir → search path. CocoaPods exposes a subspec's headers
  // under `<basename(mappings_dir)>/...` by copying them into Pods/Headers
  // preserving structure relative to the mappings dir. SPM has no such copy
  // step, so namespaced includes like `<reanimated/apple/sensor/X.h>` (header
  // physically at `apple/reanimated/apple/sensor/X.h`, mappings dir
  // `apple/reanimated`) only resolve if the mappings dir's PARENT (`apple`) is
  // on the search path. Add dirname() of every subspec's mappings dir.
  for (const mappingsDir of model.headerMappingsDirs) {
    const parent = path.posix.dirname(mappingsDir.replace(/^\.\//, ''));
    // dirname of a single-segment dir is "." (root) — already implicitly
    // searched; skip it and anything that doesn't exist on disk.
    if (
      parent.length > 0 &&
      parent !== '.' &&
      !headerSearchPaths.includes(parent) &&
      fs.existsSync(path.join(dep.root, parent))
    ) {
      headerSearchPaths.push(parent);
    }
  }

  // Bucket dependencies. React-Core / React-jsi / RCT-Folly / glog etc. ALL
  // collapse to the invariant React header products
  // reference because they're bundled in the prebuilt React.xcframework.
  // Sibling RN libs (autolinked or self-managed deps) flow through the
  // existing spm-deps mechanism. Unknown names are dropped with a warning.
  let coreReactNative = false;
  const siblingNames /*: Array<string> */ = [];
  const externalPackages /*: Array<{pod: string, url: string, exact: string, product: string, package: string}> */ = [];
  const unmappedPods /*: Array<string> */ = [];
  const selfPodspecName = model.name;
  for (const depName of model.dependencies) {
    // Cross-subspec refs like "react-native-safe-area-context/common" are a
    // CocoaPods construct for one subspec depending on another from the
    // SAME podspec. After flattenSubspecs has merged everything into one
    // target the subspec ref is meaningless — drop silently.
    if (depName.includes('/') && depName.startsWith(`${selfPodspecName}/`)) {
      continue;
    }
    const podSibling = podToNpm.get(depName.split('/')[0]);
    if (isReactCoreDep(depName)) {
      coreReactNative = true;
    } else if (depName.startsWith('react-native-')) {
      // Generic cross-subspec ref guard for any "package/subspec" form.
      const baseName = depName.split('/')[0];
      if (!siblingNames.includes(baseName)) {
        siblingNames.push(baseName);
      }
    } else if (podSibling != null && podSibling !== dep.name) {
      // A pod-style dependency name (e.g. reanimated's `s.dependency
      // "RNWorklets"`) that resolves to an autolinked sibling's npm package
      // (react-native-worklets). Wire it as a sibling .package/.product so
      // the dep's cross-package includes (`<worklets/...>`) resolve.
      if (!siblingNames.includes(podSibling)) {
        siblingNames.push(podSibling);
      }
    } else if (isExpoModuleDep(depName)) {
      warnings.push(
        `Unknown dependency "${depName}" — not wired into the scaffolded Package.swift. Edit manually if needed.`,
      );
    } else {
      // A CocoaPods pod ("SwiftUIIntrospect", "MMKV"): wire it to its SwiftPM
      // package when the map knows one, else say loudly that the build may fail.
      const pod = depName.split('/')[0];
      const known = Object.hasOwn(KNOWN_POD_SPM_PACKAGES, pod)
        ? KNOWN_POD_SPM_PACKAGES[pod]
        : null;
      if (known != null) {
        if (!externalPackages.some(e => e.pod === pod)) {
          externalPackages.push({pod, ...known, package: spmPackageIdentity(known.url)});
        }
      } else if (!unmappedPods.includes(pod)) {
        unmappedPods.push(pod);
        warnings.push(
          `Dependency "${pod}" is a CocoaPods pod with no known SwiftPM equivalent; the scaffolded package may fail to build — add it to the pod→SwiftPM map in scaffold-package-swift.js`,
        );
      }
    }
  }

  // New-Architecture libraries declare their React-core dependency via the
  // `install_modules_dependencies(s)` podspec helper (which auto-adds
  // React-Core / React-RCTFabric / React-Codegen), NOT an explicit
  // `s.dependency "React-Core"`. We strip that helper when evaluating the
  // podspec, so the React-core dependency never surfaces in model.dependencies
  // and `coreReactNative` would stay false. The authoritative, RN-standard
  // marker for "this lib participates in the New Architecture / codegen" is a
  // `codegenConfig` block in package.json — when present, the app's codegen has
  // generated `react/renderer/components/<name>/{ShadowNodes,Props,…}.h` that
  // the lib's Fabric sources include via angle brackets. Those generated
  // headers live in the per-app React-GeneratedCode package, so the lib must
  // depend on it (and, transitively, on React core). Treat codegenConfig as
  // an implicit React-core dependency.
  // `codegenConfig` only marks Fabric/New-Arch libraries. A plain ObjC module
  // (e.g. rn-tester's TestLibrary*) that wires React core solely through
  // `install_modules_dependencies(s)` has no codegenConfig — but the helper's
  // presence is itself an authoritative "depends on React core" signal, so
  // treat it the same way.
  if (
    !coreReactNative &&
    (depHasCodegenConfig(dep.root) ||
      model.usesInstallModulesDependencies === true)
  ) {
    coreReactNative = true;
  }

  // SPM's `sources:` field does NOT accept CocoaPods-style globs — it wants
  // a list of explicit file paths (relative to the target's `path:`).
  // Expand the podspec globs against the actual filesystem so the emitted
  // Package.swift parses cleanly.
  let expandedSources /*: Array<string> */ = [];
  try {
    expandedSources = expandSpmSourceGlobs(dep.root, model.sourceFiles);
  } catch (e) {
    warnings.push(
      `Source glob expansion failed (${e.message}); emitting raw globs — SPM will likely reject them.`,
    );
    expandedSources = model.sourceFiles;
  }
  // Strip files matching exclude_files (podspec's negation list).
  if (model.excludeFiles.length > 0) {
    try {
      // $FlowFixMe[untyped-import] micromatch has no types
      const micromatch = require('micromatch');
      const isExcluded = micromatch.matcher(model.excludeFiles);
      expandedSources = expandedSources.filter(f => !isExcluded(f));
    } catch (e) {
      warnings.push(
        `exclude_files filtering failed (${e.message}); keeping all sources.`,
      );
    }
  }
  // Never self-ingest scaffold artifacts: a re-scaffold runs with the
  // previous run's output on disk, and root-level podspec globs sweep it
  // into sources — `*.{h,...,swift}` matches Package.swift itself, whose
  // `.swift` extension then trips the mixed-language gate into DELETING the
  // manifest it just wrote (alternating scaffold/self-destruct runs); the
  // prefix header and the include/ shim mirror would similarly feed back.
  expandedSources = expandedSources.filter(
    f =>
      f !== SCAFFOLD_PREFIX_HEADER &&
      f !== 'Package.swift' &&
      !/^Package@swift-[\d.]+\.swift$/.test(f) &&
      !f.startsWith('include/') &&
      !f.startsWith(`${MIXED_SUPPORT_DIR}/`) &&
      !f.startsWith(`${REACT_BARE_HEADERS_DIR}/`),
  );

  // Metal shaders: SwiftPM compiles every `.metal` file under the target path
  // (listed in `sources:` or not: it processes them as resources) in a
  // `CompileMetalFile` step that needs the `metal` compiler, which only ships
  // with Xcode (macOS). On any other host the build dies with `unable to spawn
  // process 'metal'`, so drop them from sources/resources and `exclude:` them
  // from the target there (or with RN_SPM_SKIP_METAL=1).
  let resources = model.resources;
  const excludePaths /*: Array<string> */ = [];
  if (process.platform !== 'darwin' || process.env.RN_SPM_SKIP_METAL === '1') {
    const isMetal = (f /*: string */) => /\.metal$/i.test(f);
    let onDisk /*: Array<string> */ = [];
    try {
      onDisk = expandSpmSourceGlobs(dep.root, ['**/*.metal']);
    } catch {
      // best-effort: sources/resources below are still filtered
    }
    const skipped = Array.from(
      new Set([
        ...onDisk,
        ...expandedSources.filter(isMetal),
        ...resources.filter(isMetal),
      ]),
    ).sort();
    if (skipped.length > 0) {
      expandedSources = expandedSources.filter(f => !isMetal(f));
      resources = resources.filter(f => !isMetal(f));
      excludePaths.push(...skipped);
      const names = Array.from(
        new Set(skipped.map(f => path.posix.basename(f))),
      );
      warnings.push(
        `Skipped ${names.length} Metal shader(s) (${names.join(', ')}) — the Metal compiler is only available on macOS; features relying on them are unavailable in this build.`,
      );
    }
  }

  // Header-map emulation: CocoaPods builds a header map (USE_HEADERMAP=YES by
  // default) so a source can `#import "Foo.h"` by bare name regardless of which
  // subdirectory Foo.h lives in. SPM has no header map, so add every directory
  // that contains a header to the search path. Covers libs (e.g. svg) that
  // spread flat-named headers across many subdirs.
  const isHeader = (f /*: string */) => /\.(h|hh|hpp)$/i.test(f);
  const headerFiles = expandedSources.filter(isHeader);
  try {
    for (const f of expandSpmSourceGlobs(dep.root, model.publicHeaderFiles)) {
      if (/\.(h|hh|hpp)$/i.test(f)) headerFiles.push(f);
    }
  } catch {
    // public_header_files globbing is best-effort — source_files usually
    // already covers the headers.
  }
  for (const f of headerFiles) {
    const d = path.posix.dirname(f);
    addSearchPath(d === '' ? '.' : d);
  }

  // ObjC(++) sources may rely on CocoaPods' implicit prefix-header import of
  // Foundation/UIKit. When present, emit + `-include` a prefix header (below).
  // The prefix is `-include`d by bare name, so the dep root (".") must be on
  // the header search path for clang to find it.
  const needsObjCPrefix = expandedSources.some(f => /\.mm?$/.test(f));
  if (needsObjCPrefix && !headerSearchPaths.includes('.')) {
    headerSearchPaths.push('.');
  }

  // SPM REQUIRES publicHeadersPath to be a real directory inside the target
  // when the target compiles C-family sources (default is "include" which
  // typically doesn't exist in a podspec-shaped dep). Pick the first
  // existing prefix dir from public_header_files / source_files. The
  // chosen dir doesn't need to be the include surface — path-style
  // includes (`<react/renderer/.../X.h>`) resolve via headerSearchPaths
  // instead. publicHeadersPath just has to point at a real dir containing
  // some .h files so SPM accepts the target definition.
  let publicHeadersPath /*: ?string */ = null;
  // Prefer the namespace root (parent of a header_mappings_dir). SPM propagates
  // a target's publicHeadersPath to DEPENDENT packages as a search path, so
  // setting it to e.g. `Common/cpp` (parent of `Common/cpp/worklets`) is what
  // lets a sibling package resolve `<worklets/...>`. Prefer a cross-platform
  // (Common) dir — that holds the C++ API siblings consume — over a
  // platform-specific (apple/) one.
  const mappingsParents = model.headerMappingsDirs
    .map(d => path.posix.dirname(d.replace(/^\.\//, '')))
    .filter(
      p => p.length > 0 && p !== '.' && fs.existsSync(path.join(dep.root, p)),
    );
  if (mappingsParents.length > 0) {
    publicHeadersPath =
      mappingsParents.find(p => /(?:^|\/)common(?:\/|$)/i.test(p)) ??
      mappingsParents[0];
  }
  if (publicHeadersPath == null) {
    for (const glob of [...model.publicHeaderFiles, ...model.sourceFiles]) {
      const prefix = glob.split('/')[0];
      if (
        prefix.length > 0 &&
        !prefix.includes('*') &&
        fs.existsSync(path.join(dep.root, prefix))
      ) {
        publicHeadersPath = prefix;
        break;
      }
    }
  }
  let namespacedShimHeaders /*: Array<string> */ = [];
  // SwiftPM rejects a publicHeadersPath that holds the umbrella header
  // `<SwiftName>.h` next to subdirectories ("invalid header layout: umbrella
  // header found ... but directories exist next to it"). Fall back to the
  // generated include/<SwiftName>/ shim, fed with every header among the
  // sources; the header search paths above keep bare `#import "X.h"` working.
  if (publicHeadersPath != null) {
    const phDir = path.join(dep.root, publicHeadersPath);
    const umbrellaNextToSubdirs =
      fs.existsSync(path.join(phDir, `${swiftName}.h`)) &&
      fs.readdirSync(phDir, {withFileTypes: true}).some(e => e.isDirectory());
    if (umbrellaNextToSubdirs) {
      // On a basename collision keep the shallowest path (fewest '/'), then
      // the lexicographically first, so the choice is deterministic.
      const byDepth = [...headerFiles].sort(
        (a, b) =>
          a.split('/').length - b.split('/').length || (a < b ? -1 : a > b ? 1 : 0),
      );
      const seen /*: Map<string, string> */ = new Map();
      for (const h of byDepth) {
        const base = path.posix.basename(h);
        if (seen.has(base)) {
          if (seen.get(base) !== h) {
            warnings.push(
              `Header basename collision in include/${swiftName}/: keeping '${seen.get(base) ?? ''}', skipping '${h}'.`,
            );
          }
          continue;
        }
        seen.set(base, h);
      }
      namespacedShimHeaders = [...seen.values()];
      publicHeadersPath = 'include';
    }
  }
  if (publicHeadersPath == null) {
    // Root-level podspecs (`s.source_files = "*.{h,m,mm}"`) keep their
    // headers in the package root. CocoaPods exposes them to dependents as
    // `#import <PodName/Header.h>` via header maps; SPM has no equivalent, so
    // the scaffold writer mirrors them into a generated include/<SwiftName>/
    // shim dir and publicHeadersPath points there (also fixing SPM's
    // rejection over the nonexistent default `include/`).
    const rootHeaders = expandedSources.filter(
      f => f.endsWith('.h') && !f.includes('/'),
    );
    if (rootHeaders.length > 0) {
      namespacedShimHeaders = rootHeaders;
      publicHeadersPath = 'include';
    }
  }
  if (publicHeadersPath == null) {
    warnings.push(
      `Could not infer publicHeadersPath from source globs. SPM may reject the target — add a publicHeadersPath manually to the scaffolded Package.swift.`,
    );
  }

  // CocoaPods `header_dir` exposes a spec's headers, flattened, as
  // `<header_dir/X.h>` whatever their subdirectory. Mirror each as a stub in
  // include/<header_dir>/ and put include/ on the header search path.
  const headerDirShims /*: Array<{dir: string, headers: Array<string>}> */ = [];
  const headerDirsSeen /*: Set<string> */ = new Set();
  for (const scope of model.headerDirScopes ?? []) {
    // The directory name is written under include/: refuse anything that could
    // leave it (`..`, an absolute path).
    if (
      path.posix.isAbsolute(scope.headerDir) ||
      path.win32.isAbsolute(scope.headerDir) ||
      scope.headerDir.split(/[\\/]/).includes('..')
    ) {
      warnings.push(
        `Ignoring header_dir '${scope.headerDir}': it must be a relative path without '..'; no <header_dir/...> stubs emitted for it.`,
      );
      continue;
    }
    if (headerDirsSeen.has(scope.headerDir)) {
      warnings.push(
        `Two header_dir scopes share include/${scope.headerDir}/: their stubs land in the same directory and a header with the same name from the later scope overwrites the earlier one.`,
      );
    }
    headerDirsSeen.add(scope.headerDir);
    if (scope.headerDir === swiftName) {
      warnings.push(
        `header_dir '${scope.headerDir}' equals the target name: its stubs share include/${swiftName}/ with the umbrella-header shims.`,
      );
    }
    let files /*: Array<string> */ = [];
    try {
      files = expandSpmSourceGlobs(dep.root, scope.sourceFiles);
      if (model.excludeFiles.length > 0) {
        // $FlowFixMe[untyped-import] micromatch has no types
        const isExcluded = require('micromatch').matcher(model.excludeFiles);
        files = files.filter(f => !isExcluded(f));
      }
    } catch (e) {
      warnings.push(
        `header_dir '${scope.headerDir}': glob expansion failed (${e.message}); no <${scope.headerDir}/...> headers emitted.`,
      );
      continue;
    }
    const byDepth = files
      .filter(f => isHeader(f) && !f.startsWith('include/'))
      .sort(
        (a, b) =>
          a.split('/').length - b.split('/').length || (a < b ? -1 : a > b ? 1 : 0),
      );
    const seen /*: Map<string, string> */ = new Map();
    for (const h of byDepth) {
      const base = path.posix.basename(h);
      if (seen.has(base)) {
        warnings.push(
          `Header basename collision in include/${scope.headerDir}/: keeping '${seen.get(base) ?? ''}', skipping '${h}'.`,
        );
        continue;
      }
      seen.set(base, h);
    }
    if (seen.size > 0) {
      headerDirShims.push({dir: scope.headerDir, headers: [...seen.values()]});
    }
  }
  if (
    headerDirShims.length > 0 &&
    publicHeadersPath !== 'include' &&
    !headerSearchPaths.includes('include')
  ) {
    headerSearchPaths.push('include');
  }

  const siblingSwiftNames /*: {[npmName: string]: string} */ = {};
  for (const npmName of siblingNames) {
    const resolved = swiftNameByNpm.get(npmName);
    if (resolved != null) {
      siblingSwiftNames[npmName] = resolved;
    }
  }

  // New Architecture macro. CocoaPods defines it for every pod that calls
  // `install_modules_dependencies` (scripts/cocoapods/new_architecture.rb,
  // `computeFlags`: `-DRCT_NEW_ARCH_ENABLED=1`), and expo's autolinking emits
  // the same `.define("RCT_NEW_ARCH_ENABLED", to: "1")` for its own targets;
  // nothing under scripts/spm does, so a scaffolded RN library would compile
  // its Paper code paths (and Fabric views would be missing at runtime). Added
  // only for React Native libraries (`coreReactNative`: React-* dependency,
  // `codegenConfig` or `install_modules_dependencies`) and only when the
  // podspec did not set it already (globally; a config-scoped define does
  // not count). The Folly macros are NOT added, and the podspec's own
  // `-DFOLLY_*` are dropped by read-podspec: folly/portability/Config.h
  // includes the prebuilt headers' folly-config.h, which already defines
  // FOLLY_MOBILE/FOLLY_USE_LIBCPP/... (defining FOLLY_NO_CONFIG would turn
  // that include off).
  const preprocessorDefines = [...model.preprocessorDefines];
  if (
    coreReactNative &&
    // A Debug-only define must not suppress the global one.
    !preprocessorDefines.some(
      d => d.name === 'RCT_NEW_ARCH_ENABLED' && d.config == null,
    )
  ) {
    preprocessorDefines.push({
      name: 'RCT_NEW_ARCH_ENABLED',
      value: '1',
      config: null,
    });
  }

  const reactBareHeaders = coreReactNative
    ? bareReactHeaders(
        dep.root,
        expandedSources.filter(f => isClangSource(f) || isHeader(f)),
        headerSearchPaths,
        includeRoots,
      )
    : [];
  if (
    reactBareHeaders.length > 0 &&
    !headerSearchPaths.includes(REACT_BARE_HEADERS_DIR)
  ) {
    headerSearchPaths.push(REACT_BARE_HEADERS_DIR);
  }

  // Mixed Swift + C-family sources → one mixed-language target (see
  // MIXED_TOOLS_VERSION_LINE). Swift Build names the generated header after
  // the TARGET (`react-native-foo-Swift.h`), not after the c99 module name;
  // sources written for CocoaPods spell it after the pod's module
  // (module_name, else header_dir, else the pod name, c99), with or without a
  // `<Module>/` prefix, so forwarding shims cover those.
  let mixedLanguage = null;
  if (
    expandedSources.some(isSwiftSource) &&
    expandedSources.some(isClangSource)
  ) {
    const swiftHeader = `${swiftName}-Swift.h`;
    const podModule = toC99Name(
      model.moduleName ?? model.headerDir ?? model.name ?? swiftName,
    );
    let podspecText = '';
    try {
      const podspecPath =
        dep.platforms.ios?.podspecPath ?? findPodspecs(dep.root)[0];
      if (podspecPath != null) {
        podspecText = fs.readFileSync(podspecPath, 'utf8');
      }
    } catch {
      // No podspec text: no declared bridging header.
    }
    const declared = podspecBridgingHeader(podspecText);
    if (declared === null) {
      warnings.push(
        `The podspec sets SWIFT_OBJC_BRIDGING_HEADER to a value that cannot be resolved; the generated ${MIXED_SUPPORT_DIR}/${MIXED_UMBRELLA_HEADER} is used instead.`,
      );
    }
    let umbrellaHeaders /*: Array<string> */ = [];
    if (typeof declared !== 'string') {
      const {safe, cxx} = swiftImportableHeaders(
        dep.root,
        Array.from(new Set(headerFiles))
          .filter(
            h =>
              /\.h$/i.test(h) &&
              !h.startsWith('include/') &&
              !h.startsWith(`${MIXED_SUPPORT_DIR}/`),
          )
          .sort(),
        headerSearchPaths,
        includeRoots,
      );
      umbrellaHeaders = safe;
      if (cxx.length > 0) {
        warnings.push(
          `Left ${cxx.length} C++ header(s) out of the Swift umbrella (${MIXED_SUPPORT_DIR}/${MIXED_UMBRELLA_HEADER}): ${cxx.join(', ')}. Swift cannot import C++; Objective-C(++) sources still see them.`,
        );
      }
    }
    if (process.env[SWIFT_HEADERS_DIR_ENV] == null) {
      warnings.push(
        `Mixed Swift + Objective-C target: set ${SWIFT_HEADERS_DIR_ENV} to the build's GeneratedModuleMaps-<platform> directory when building, so Objective-C finds ${swiftHeader}. Unset, the manifest falls back to this package's own ${SWIFT_HEADERS_FALLBACK}.`,
      );
    }
    mixedLanguage = {
      swiftHeader,
      podModule,
      bridgingHeader:
        typeof declared === 'string'
          ? declared
          : `${MIXED_SUPPORT_DIR}/${MIXED_UMBRELLA_HEADER}`,
      umbrellaHeaders: typeof declared === 'string' ? null : umbrellaHeaders,
    };
    if (!headerSearchPaths.includes(MIXED_SUPPORT_DIR)) {
      headerSearchPaths.push(MIXED_SUPPORT_DIR);
    }
  }

  return {
    swiftName,
    mixedLanguage,
    reactBareHeaders,
    sources: expandedSources,
    headerSearchPaths,
    preprocessorDefines,
    needsObjCPrefix,
    coreReactNative,
    siblingNames,
    siblingSwiftNames,
    externalPackages,
    extraFrameworks: model.frameworks,
    weakFrameworks: model.weakFrameworks,
    compilerFlags: model.compilerFlags,
    publicHeadersPath,
    namespacedShimHeaders,
    headerDirShims,
    resources,
    excludePaths,
    warnings,
  };
}

// ---------------------------------------------------------------------------
// Swift emission
// ---------------------------------------------------------------------------

/*::
type EmitContext = {
  // Identifier embedded as a comment so SPM's manifest hash bumps when the
  // active xcframework slot changes (otherwise cached evaluations would
  // keep pointing at the prior slot's headers).
  cacheSlotLabel: ?string,
  // Remote SPM package mode (url/version/identity) — see remotePackageConfig.
  remote?: ?{url: string, version: string, identity: string},
  // Relative path (posix, from the dep's package dir) to the app's codegen
  // package (<appRoot>/build/generated/ios). Computed at scaffold time —
  // safe because the file is re-scaffolded per app/cache slot, and any
  // node_modules relayout implies a reinstall that drops the file anyway.
  codegenPackageDir?: ?string,
  // Relative path to the app's local xcframeworks package
  // (<appRoot>/build/xcframeworks). Only referenced when remote == null.
  localXcfwPackageDir?: ?string,
  iosDeploymentTarget?: ?string,
};
*/

/**
 * Renders the SpmScaffoldSpec to a complete Package.swift string suitable
 * for writing into `node_modules/<dep>/`. Fully declarative: all package
 * references are plain relative paths computed at scaffold time (no runtime
 * discovery — the scaffolder knows both the dep dir and the app root, and
 * re-scaffolds whenever either could have moved).
 */
function emitScaffoldedPackageSwift(
  spec /*: SpmScaffoldSpec */,
  ctx /*:: ?: EmitContext */ = {cacheSlotLabel: null, remote: null},
) /*: string */ {
  const slotComment =
    ctx.cacheSlotLabel != null ? `\n// Cache slot: ${ctx.cacheSlotLabel}` : '';
  const iosDeploymentTarget /*: string */ =
    ctx.iosDeploymentTarget ?? MIN_IOS_VERSION_SUPPORTED;

  // React headers need NO search paths — they come from the React /
  // ReactNativeHeaders binaryTargets and the ReactAppHeaders product (see
  // the dependencies block below). Per-dep HEADER_SEARCH_PATHS from the
  // podspec are emitted as `.headerSearchPath("<rel>")` so they resolve
  // relative to `path:` ("." below). Custom podspec compiler flags keep
  // using unsafeFlags (rare; surfaced verbatim).
  const customFlagsCxx = spec.compilerFlags.map(f => `"${f}"`);

  const headerSearchPathDirectives = spec.headerSearchPaths
    .map(p => `.headerSearchPath("${p}")`)
    .join(', ');

  // Preprocessor defines → `.define("NAME", to: "VALUE", .when(...))`. The
  // value is escaped as a Swift string literal because it may itself contain
  // quotes (e.g. a string-literal macro `-DFOO="[A:false]"`).
  const swiftStr = (s /*: string */) =>
    `"${s.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`;
  const defineDirectives = (spec.preprocessorDefines ?? [])
    .map(d => {
      const toPart = d.value != null ? `, to: ${swiftStr(d.value)}` : '';
      const condPart =
        d.config === 'debug'
          ? ', .when(configuration: .debug)'
          : d.config === 'release'
            ? ', .when(configuration: .release)'
            : '';
      return `.define(${swiftStr(d.name)}${toPart}${condPart})`;
    })
    .join(', ');

  const settingsEntries = (extra /*: Array<string> */) => {
    const parts = [
      defineDirectives,
      headerSearchPathDirectives,
      ...extra,
    ].filter(e => e.length > 0);
    return `[${parts.join(', ')}]`;
  };
  // Force-include the ambient-import prefix header on ObjC(++) sources (the
  // `__OBJC__` guard makes it a no-op for plain C/C++). `-include` resolves the
  // bare name via the dep-root header search path (".", ensured in translate).
  const prefixFlag = spec.needsObjCPrefix
    ? `.unsafeFlags(["-include", "${SCAFFOLD_PREFIX_HEADER}"])`
    : '';
  // Mixed-language target: ObjC(++) finds `<Module>-Swift.h` in the Swift
  // Build headers dir (see MIXED_TOOLS_VERSION_LINE).
  const mixed = spec.mixedLanguage ?? null;
  const swiftHeadersFlag =
    mixed != null ? '.unsafeFlags(["-I", rnSpmSwiftHeadersDir])' : '';
  // SwiftPM 6.4's swiftbuild backend does not apply the package's
  // `cxxLanguageStandard` to a mixed-language target (its ObjC++/C++ files
  // compile with the clang default and fail on React's C++20 headers), so the
  // standard is passed explicitly.
  const mixedCxxStdFlag =
    mixed != null ? '.unsafeFlags(["-std=c++20"])' : '';
  const cSettings = settingsEntries(
    [prefixFlag, swiftHeadersFlag].filter(e => e.length > 0),
  );
  const cxxSettings = settingsEntries(
    [
      prefixFlag,
      swiftHeadersFlag,
      mixedCxxStdFlag,
      ...(customFlagsCxx.length > 0
        ? [`.unsafeFlags([${customFlagsCxx.join(', ')}])`]
        : []),
      // Match the prebuilt React.framework's config-gated C++ ABI. NDEBUG in
      // Release strips DebugStringConvertible's vtable (and shifts the
      // ShadowNode layout that inherits it), so a Fabric C++ target compiled
      // WITHOUT NDEBUG fails to link against a Release React.framework. Mirrors
      // packages/react-native/Package.swift's own C++ targets.
      ...REACT_CXX_CONFIG_DEFINES,
    ].filter(e => e.length > 0),
  );

  // Linker frameworks: defaults + podspec-declared extras + weak frameworks.
  // Dedup on render so the user doesn't see duplicate UIKit lines.
  const defaults = ['UIKit', 'Foundation', 'CoreGraphics'];
  const linkedFrameworks = Array.from(
    new Set([...defaults, ...spec.extraFrameworks]),
  );
  const linkerEntries = [
    ...linkedFrameworks.map(f => `.linkedFramework("${f}")`),
    ...spec.weakFrameworks.map(
      f => `.linkedFramework("${f}", .when(platforms: [.iOS]))`,
    ),
  ];

  // Dependencies block. Always declares ReactNative if any React-core dep
  // was in the podspec; sibling RN deps come from autolinking's existing
  // .package(path: ...) graph, under the names the autolinker resolved.
  const packageDeps /*: Array<string> */ = [];
  const targetDeps /*: Array<string> */ = [];
  if (spec.coreReactNative) {
    // Remote mode: React Native comes from the remote package identity (no
    // app-layout knowledge). The per-app codegen package is generated INTO
    // the app by definition, so it stays a path reference — relative,
    // computed at scaffold time.
    const remote = ctx.remote;
    const rnLabel =
      remote != null ? remote.identity : REACT_NATIVE_PACKAGE_NAME;
    const codegenDir = ctx.codegenPackageDir;
    if (codegenDir == null) {
      throw new Error(
        'emitScaffoldedPackageSwift: codegenPackageDir is required when the dep depends on React core.',
      );
    }
    if (remote != null) {
      packageDeps.push(
        `.package(url: "${remote.url}", exact: "${remote.version}")`,
      );
    } else {
      const xcfwDir = ctx.localXcfwPackageDir;
      if (xcfwDir == null) {
        throw new Error(
          'emitScaffoldedPackageSwift: localXcfwPackageDir is required when no remote package is configured.',
        );
      }
      packageDeps.push(
        `.package(name: "${REACT_NATIVE_PACKAGE_NAME}", path: "${xcfwDir}")`,
      );
    }
    packageDeps.push(
      `.package(name: "${REACT_CODEGEN_PACKAGE_NAME}", path: "${codegenDir}")`,
    );
    for (const product of REACT_NATIVE_PRODUCTS) {
      targetDeps.push(`.product(name: "${product}", package: "${rnLabel}")`);
    }
    for (const product of REACT_CODEGEN_PRODUCTS) {
      targetDeps.push(
        `.product(name: "${product}", package: "${REACT_CODEGEN_PACKAGE_NAME}")`,
      );
    }
  }
  for (const siblingName of spec.siblingNames) {
    const swiftSibling = spec.siblingSwiftNames?.[siblingName];
    if (swiftSibling == null) {
      throw new Error(
        `react-native spm scaffold: no resolved Swift name for the sibling '${siblingName}'. expandSpmDependencies must resolve every dep's name before a manifest is written.`,
      );
    }
    // The autolinker references each self-managed (scaffolded) dep through a
    // `libs/<SwiftName>` symlink, and SPM resolves a manifest's relative
    // package paths against that symlink location — so a sibling lives at
    // `../<SwiftName>` (NOT `../<npm-name>`, which would be `libs/<npm-name>`
    // and not exist).
    packageDeps.push(
      `.package(name: "${swiftSibling}", path: "../${swiftSibling}")`,
    );
    targetDeps.push(
      `.product(name: "${swiftSibling}", package: "${swiftSibling}")`,
    );
  }
  // CocoaPods pods with a known SwiftPM package (KNOWN_POD_SPM_PACKAGES).
  for (const ext of spec.externalPackages ?? []) {
    packageDeps.push(`.package(url: "${ext.url}", exact: "${ext.exact}")`);
    targetDeps.push(`.product(name: "${ext.product}", package: "${ext.package}")`);
  }

  // sources: emit only when the podspec declared them. If empty (regex-fallback
  // podspec), no `sources:`/`exclude:` is emitted and SPM auto-scans the target
  // dir — which for `path: "."` is the entire dep root. That is a known
  // limitation of the regex-fallback path (the pod-ipc parse yields explicit
  // sources); a future improvement could emit an `exclude:` list for the dep's
  // example/test/build dirs.
  const sourcesLine =
    spec.sources.length > 0
      ? `\n            sources: [\n${spec.sources.map(s => `                "${s}",`).join('\n')}\n            ],`
      : '';

  const publicHeadersLine =
    spec.publicHeadersPath != null
      ? `\n            publicHeadersPath: "${spec.publicHeadersPath}",`
      : '';

  const excludeLine =
    (spec.excludePaths ?? []).length > 0
      ? `\n            exclude: [${(spec.excludePaths ?? []).map(e => `"${e}"`).join(', ')}],`
      : '';

  const resourcesLine =
    spec.resources.length > 0
      ? `\n            resources: [${spec.resources.map(r => `.copy("${r}")`).join(', ')}],`
      : '';

  const packageDepsBlock =
    packageDeps.length > 0
      ? `    dependencies: [\n        ${packageDeps.join(',\n        ')},\n    ],\n`
      : '';

  const targetDepsLine =
    targetDeps.length > 0
      ? `\n            dependencies: [${targetDeps.join(', ')}],`
      : '';

  const toolsVersionLine =
    mixed != null ? MIXED_TOOLS_VERSION_LINE : '// swift-tools-version: 6.0';
  const mixedLets =
    mixed != null
      ? `
// Mixed Swift + Objective-C target (one SwiftPM mixed-language target). Objective-C
// finds ${mixed.swiftHeader} in the directory Swift Build writes it to,
// which belongs to the root build: the build passes it in
// ${SWIFT_HEADERS_DIR_ENV}. Swift sees the module's Objective-C through
// ${mixed.bridgingHeader}.
let rnSpmSwiftHeadersDir = Context.environment["${SWIFT_HEADERS_DIR_ENV}"]
    ?? (Context.packageDirectory + "/${SWIFT_HEADERS_FALLBACK}")
let rnSpmBridgingHeader = Context.packageDirectory + "/${mixed.bridgingHeader}"
`
      : '';
  const swiftSettingsLine =
    mixed != null
      ? `\n            swiftSettings: [.unsafeFlags(["-import-objc-header", rnSpmBridgingHeader])],`
      : '';

  return `${toolsVersionLine}
${SCAFFOLDER_MARKER}
// AUTO-SCAFFOLDED-VERSION: ${SCAFFOLDER_VERSION}
// rn-xtool-scaffold-revision: ${RN_XTOOL_SCAFFOLD_REVISION}${slotComment}
// Edit the contents below if needed and re-run \`npx patch-package <dep-name>\`
// to persist across \`npm install\`. To regenerate from the podspec, remove
// this file (or just this marker) and re-run \`npx react-native spm scaffold\`.
//
// Package references are plain relative paths, computed when this file was
// scaffolded. They stay correct because the file is re-scaffolded per app
// and cache slot, and any node_modules relayout reinstalls this package
// (dropping the file) anyway.

import PackageDescription
${mixedLets}
let package = Package(
    name: "${spec.swiftName}",
    platforms: [.iOS("${iosDeploymentTarget}")],
    products: [
        .library(name: "${spec.swiftName}", targets: ["${spec.swiftName}"]),
    ],
${packageDepsBlock}    targets: [
        .target(
            name: "${spec.swiftName}",${targetDepsLine}
            path: ".",${excludeLine}${sourcesLine}${resourcesLine}${publicHeadersLine}
            cSettings: ${cSettings},
            cxxSettings: ${cxxSettings},${swiftSettingsLine}
            linkerSettings: [${linkerEntries.join(', ')}]
        ),
    ],
    cxxLanguageStandard: .cxx20
)
`;
}

const PODSPEC_KEY_ORIGINS = {
  header_dir: "its podspec's 'header_dir'",
  module_name: "its podspec's 'module_name'",
  name: 'its pod name',
};

// Null when the caller resolved the name without recording where it came from,
// since the alternative is inventing an origin.
function swiftNameOrigin(dep /*: AutolinkedDep */) /*: ?string */ {
  switch (dep.swiftNameSource) {
    case 'config':
      return "its declared 'swiftpmConfig.name'";
    case 'podspec':
      return PODSPEC_KEY_ORIGINS[dep.swiftNamePodspecKey ?? 'name'];
    case 'npm':
      return 'its npm package name';
    default:
      return null;
  }
}

/**
 * Says which SwiftPM name the library got and where that name came from. The
 * name is the prefix every `#import <Name/Header.h>` against the library has to
 * spell, and a podspec-derived one is written into the library's package.json,
 * so it is not a decision to make silently.
 */
function reportSwiftName(
  dep /*: AutolinkedDep */,
  swiftName /*: string */,
  model /*: PodspecModel */,
) /*: void */ {
  const origin = swiftNameOrigin(dep);
  if (origin == null) {
    return;
  }
  log(`${dep.name}: SwiftPM name '${swiftName}' (from ${origin}).`);
  // Two declared namespaces, one name: CocoaPods compiles the module as
  // `module_name` while consumers import through `header_dir`, so a library
  // that declares both loses one of them here.
  const {headerDir, moduleName} = model;
  if (
    dep.swiftNamePodspecKey === 'header_dir' &&
    headerDir != null &&
    moduleName != null &&
    headerDir !== moduleName
  ) {
    warn(
      `${dep.name}'s podspec declares both a 'header_dir' ('${headerDir}') and a 'module_name' ('${moduleName}'): ` +
        `'${swiftName}' is the SwiftPM name, and '${moduleName}' is not used. ` +
        `Set 'swiftpmConfig.name' in its package.json to override that choice.`,
    );
  }
}

// The local React header trees (build/xcframeworks): the React module's
// headers and the device slice of each headers xcframework.
function reactIncludeRoots(appRoot /*: string */) /*: Array<string> */ {
  const xcfw = path.join(appRoot, 'build', 'xcframeworks');
  const roots = [path.join(xcfw, 'ReactHeadersTarget', 'include')];
  try {
    for (const name of fs.readdirSync(xcfw)) {
      if (name.endsWith('.xcframework')) {
        roots.push(path.join(xcfw, name, 'ios-arm64', 'Headers'));
      }
    }
  } catch {
    // No local xcframeworks (remote mode or not set up yet).
  }
  return roots.filter(r => fs.existsSync(r));
}

/**
 * Writes the mixed-language target's support files under MIXED_SUPPORT_DIR:
 * the Swift umbrella (unless the podspec brings its own bridging header) and
 * the `<Module>-Swift.h` spellings CocoaPods sources use. The shims import the
 * real header with angle brackets so the lookup skips their own directory.
 */
function writeMixedLanguageSupport(
  depRoot /*: string */,
  mixed /*: {swiftHeader: string, podModule: string, bridgingHeader: string, umbrellaHeaders: ?Array<string>} */,
) /*: void */ {
  const dir = path.join(depRoot, MIXED_SUPPORT_DIR);
  fs.rmSync(dir, {recursive: true, force: true});
  fs.mkdirSync(path.join(dir, mixed.podModule), {recursive: true});
  const banner =
    '// AUTO-SCAFFOLDED by react-native spm scaffold (mixed Swift + Objective-C target).\n';
  if (mixed.umbrellaHeaders != null) {
    fs.writeFileSync(
      path.join(dir, MIXED_UMBRELLA_HEADER),
      banner +
        '// Swift bridging header: what the CocoaPods umbrella gives Swift — Foundation,\n' +
        '// UIKit and the module headers (minus the C++ ones Swift cannot import).\n' +
        '#import <Foundation/Foundation.h>\n' +
        '#if __has_include(<UIKit/UIKit.h>)\n#import <UIKit/UIKit.h>\n#endif\n' +
        mixed.umbrellaHeaders.map(h => `#import "../${h}"\n`).join(''),
      'utf8',
    );
  }
  const forward = `#import <${mixed.swiftHeader}>\n`;
  fs.writeFileSync(
    path.join(dir, mixed.podModule, `${mixed.podModule}-Swift.h`),
    banner + forward,
    'utf8',
  );
  if (`${mixed.podModule}-Swift.h` !== mixed.swiftHeader) {
    fs.writeFileSync(
      path.join(dir, `${mixed.podModule}-Swift.h`),
      banner + forward,
      'utf8',
    );
  }
}

// ---------------------------------------------------------------------------
// Per-dep orchestrator
// ---------------------------------------------------------------------------

/*::
type ScaffoldContext = {
  appRoot: string,
  projectRoot: string,
  reactNativeRoot: string,
  // Forces overwrite of files carrying the scaffolder marker. Files
  // WITHOUT the marker (user-edited, upstream-shipped) are never touched.
  force: boolean,
  // When true, no file is written — caller gets the would-be content and
  // can preview.
  dryRun: boolean,
  // Slot label (e.g. "0.87.0-nightly-20260513-6e262624f/debug") embedded as
  // a comment so SPM's manifest hash bumps on slot changes.
  cacheSlotLabel: ?string,
  // podspec-name → npm-name index over all autolinked deps, so pod-style
  // `s.dependency` names (e.g. "RNWorklets") wire to the right sibling.
  podToNpm?: Map<string, string>,
  // npm-name → resolved Swift name over all autolinked deps, so sibling
  // references honor each sibling's declared name.
  swiftNameByNpm?: Map<string, string>,
  remote: ?{url: string, version: string, identity: string},
  iosDeploymentTarget?: ?string,
};
*/

/**
 * Decides whether to scaffold one dep, runs the translation + emission,
 * writes the file (unless dryRun). Pure path/skip logic — all I/O via fs.
 */
function scaffoldPackageSwiftForDep(
  dep /*: AutolinkedDep */,
  ctx /*: ScaffoldContext */,
) /*: ScaffoldResult */ {
  const depName = dep.name;

  if (NEVER_SCAFFOLD.has(depName)) {
    return {
      depName,
      status: 'skipped-is-react-native',
      reason: 'react-native itself is handled by the xcframework package.',
    };
  }

  // ios platform missing → no native code to wrap.
  if (dep.platforms.ios == null) {
    return {
      depName,
      status: 'skipped-no-ios',
      reason: 'autolinking.json has no ios platform entry.',
    };
  }

  // Dep can opt out in its own package.json.
  if (
    readSwiftpmConfig(dep.root, defaultReadConfig(dep.root))?.scaffold === false
  ) {
    return {
      depName,
      status: 'skipped-opt-out',
      reason: "the library sets 'swiftpmConfig.scaffold' to false.",
    };
  }

  const pkgSwiftPath = path.join(dep.root, 'Package.swift');

  // A self-managed Package.swift may live either at the dep root (legacy
  // convention) or inside ios/ (preferred for community RN libs that want
  // their npm-package root free of SPM artifacts). If a nested manifest
  // exists and is user-authored, skip — writing a stray root manifest would
  // cause the autolinker to prefer the wrong file.
  const nestedPkgSwiftPath = path.join(dep.root, 'ios', 'Package.swift');
  if (!fs.existsSync(pkgSwiftPath) && fs.existsSync(nestedPkgSwiftPath)) {
    const nested = fs.readFileSync(nestedPkgSwiftPath, 'utf8');
    if (
      !nested.includes(AUTOGEN_MARKER) &&
      !nested.includes(SCAFFOLDER_MARKER)
    ) {
      return {
        depName,
        status: 'skipped-self-managed',
        reason:
          'Existing ios/Package.swift was not produced by this scaffolder. ' +
          'Leaving it alone.',
      };
    }
  }

  // Skip rules around existing files.
  if (fs.existsSync(pkgSwiftPath)) {
    const existing = fs.readFileSync(pkgSwiftPath, 'utf8');
    if (existing.includes(AUTOGEN_MARKER)) {
      return {
        depName,
        status: 'skipped-autogen',
        reason:
          'Existing Package.swift carries the autolinker AUTOGEN marker. ' +
          'spm update will regenerate the synth wrapper.',
      };
    }
    if (existing.includes(SCAFFOLDER_MARKER)) {
      // Version bump → unconditional regen. A bumped SCAFFOLDER_VERSION
      // implies the emitter's output format changed in a way that requires
      // regenerating existing files; --force is not needed here.
      const vMatch = existing.match(SCAFFOLDER_VERSION_LINE_RE);
      const existingVersion = vMatch != null ? parseInt(vMatch[1], 10) : 1;
      const rMatch = existing.match(RN_XTOOL_SCAFFOLD_REVISION_RE);
      const existingRevision = rMatch != null ? parseInt(rMatch[1], 10) : 0;
      const revisionStale = existingRevision < RN_XTOOL_SCAFFOLD_REVISION;
      const versionStale =
        existingVersion < SCAFFOLDER_VERSION || revisionStale;
      if (!ctx.force && !versionStale) {
        // Slot label change is the other auto-regen trigger — bumps SPM's
        // manifest hash so the cache-slot path gets re-resolved.
        const m = existing.match(/^\/\/ Cache slot: (.+)$/m);
        const existingSlot = m != null ? m[1] : null;
        if (ctx.cacheSlotLabel == null || existingSlot === ctx.cacheSlotLabel) {
          return {
            depName,
            status: 'skipped-scaffolder-marker',
            reason:
              'Already scaffolded for this cache slot. Pass --force to regenerate.',
          };
        }
      }
      if (versionStale) {
        log(
          `Re-scaffolding ${depName} (format v${existingVersion}/r${existingRevision} → v${SCAFFOLDER_VERSION}/r${RN_XTOOL_SCAFFOLD_REVISION})`,
        );
      }
      // Fall through: regenerate (force, slot changed, or version bumped).
    } else {
      // No marker at all → user-managed or upstream-shipped. Never touch.
      return {
        depName,
        status: 'skipped-self-managed',
        reason:
          'Existing Package.swift was not produced by this scaffolder. ' +
          'Leaving it alone.',
      };
    }
  }

  // autolinking.json may have provided podspecPath; otherwise search dep.root.
  // $FlowFixMe[prop-missing] dynamic shape from autolinking.json
  const podspecPath /*: ?string */ =
    dep.platforms.ios.podspecPath ?? findPodspecs(dep.root)[0];
  if (podspecPath == null || !fs.existsSync(podspecPath)) {
    return {
      depName,
      status: 'skipped-no-podspec',
      reason: 'No .podspec found in dep root.',
    };
  }

  let model;
  try {
    model = readPodspecCached(podspecPath);
  } catch (e) {
    return {
      depName,
      status: 'error',
      reason: `Podspec read failed: ${e.message}`,
    };
  }

  const spec = translatePodspecToSpmTarget(
    model,
    dep,
    ctx.podToNpm ?? new Map(),
    ctx.swiftNameByNpm ?? new Map(),
    reactIncludeRoots(ctx.appRoot),
  );

  // Mixed Swift + C-family sources used to be skipped here ("SPM cannot
  // compile them in one target"). SwiftPM >= 6.4 can, so translate emits a
  // mixed-language target instead (spec.mixedLanguage, see
  // MIXED_TOOLS_VERSION_LINE) and the writer below adds its support files.

  // Relative paths into the app, embedded in the scaffolded Package.swift.
  //
  // The manifest is written to <dep.root>/Package.swift, but the autolinker
  // references the dep through a symlink at
  // <appRoot>/build/generated/autolinking/libs/<SwiftName>. On a fresh resolve
  // SwiftPM interprets a manifest's relative `.package(path:)` entries against
  // that SYMLINK location (it does not canonicalize the symlink first), so the
  // paths must be relative to the symlink dir — NOT the real dep.root.
  // Computing from dep.root produced a doubled path
  // (…/autolinking/ios/build/generated/ios) → opaque "package manifest cannot
  // be accessed" resolution failure. posix separators, as SPM expects.
  const symlinkDir = path.join(
    ctx.appRoot,
    'build',
    'generated',
    'autolinking',
    'libs',
    spec.swiftName,
  );
  const relFromManifest = (...segments /*: Array<string> */) =>
    path
      .relative(symlinkDir, path.join(ctx.appRoot, ...segments))
      .split(path.sep)
      .join('/');
  const content = emitScaffoldedPackageSwift(spec, {
    cacheSlotLabel: ctx.cacheSlotLabel,
    remote: ctx.remote,
    iosDeploymentTarget: ctx.iosDeploymentTarget,
    codegenPackageDir: relFromManifest('build', 'generated', 'ios'),
    localXcfwPackageDir: relFromManifest('build', 'xcframeworks'),
  });

  // Distinguish "first-time scaffold" (no file at all) from "regenerate"
  // (file with the scaffolder marker, e.g. slot changed). Used by the
  // CLI orchestrator to decide whether to prompt for confirmation:
  // first-time scaffolds touch a node_modules dir the user may not expect,
  // regens are silent because we're maintaining a file we already own.
  const previouslyExisted = fs.existsSync(pkgSwiftPath);

  if (!ctx.dryRun) {
    fs.writeFileSync(pkgSwiftPath, content, 'utf8');
    const manifest65Path = path.join(dep.root, MIXED_MANIFEST_6_5);
    if (spec.mixedLanguage != null) {
      fs.writeFileSync(
        manifest65Path,
        content.replace(MIXED_TOOLS_VERSION_LINE, MIXED_TOOLS_VERSION_LINE_6_5),
        'utf8',
      );
    } else if (
      fs.existsSync(manifest65Path) &&
      fs.readFileSync(manifest65Path, 'utf8').includes(SCAFFOLDER_MARKER)
    ) {
      fs.rmSync(manifest65Path, {force: true});
    }
    // Emit the ambient-import prefix header next to the manifest when the
    // target has ObjC(++) sources (the manifest `-include`s it by bare name).
    if (spec.needsObjCPrefix) {
      fs.writeFileSync(
        path.join(dep.root, SCAFFOLD_PREFIX_HEADER),
        SCAFFOLD_PREFIX_HEADER_CONTENTS,
        'utf8',
      );
    }
    // Mirror root-level headers into the generated include/<SwiftName>/ shim
    // dir (publicHeadersPath) so dependents can use the CocoaPods header-map
    // spelling `#import <SwiftName/Header.h>`.
    if (spec.namespacedShimHeaders.length > 0) {
      const shimDir = path.join(dep.root, 'include', spec.swiftName);
      fs.mkdirSync(shimDir, {recursive: true});
      for (const header of spec.namespacedShimHeaders) {
        // Entries may be nested relative paths (e.g. apple/Handlers/X.h): the
        // stub is named by basename and #imports the real header by path.
        const name = path.posix.basename(header);
        fs.writeFileSync(
          path.join(shimDir, name),
          `// AUTO-SCAFFOLDED by react-native spm scaffold — the namespaced\n` +
            `// spelling (<${spec.swiftName}/${name}>) of the header,\n` +
            `// matching how CocoaPods header maps expose it.\n` +
            `#import "../../${header}"\n`,
          'utf8',
        );
      }
    }
    // `header_dir` namespaces: one stub per header in include/<header_dir>/.
    for (const {dir, headers} of spec.headerDirShims) {
      const nsDir = path.join(dep.root, 'include', dir);
      fs.mkdirSync(nsDir, {recursive: true});
      for (const header of headers) {
        const name = path.posix.basename(header);
        fs.writeFileSync(
          path.join(nsDir, name),
          `// AUTO-SCAFFOLDED by react-native spm scaffold — the <${dir}/${name}>\n` +
            `// spelling CocoaPods' header_dir gives the header.\n` +
            `#import "${'../'.repeat(dir.split('/').length + 1)}${header}"\n`,
          'utf8',
        );
      }
    }
  }

  if (!ctx.dryRun && spec.mixedLanguage != null) {
    writeMixedLanguageSupport(dep.root, spec.mixedLanguage);
  }
  if (!ctx.dryRun) {
    const bareDir = path.join(dep.root, REACT_BARE_HEADERS_DIR);
    fs.rmSync(bareDir, {recursive: true, force: true});
    if (spec.reactBareHeaders.length > 0) {
      fs.mkdirSync(bareDir, {recursive: true});
      for (const name of spec.reactBareHeaders) {
        fs.writeFileSync(
          path.join(bareDir, name),
          `// AUTO-SCAFFOLDED by react-native spm scaffold — the bare "${name}"\n` +
            `// spelling CocoaPods' header map resolves to React's public header.\n` +
            `#import <React/${name}>\n`,
          'utf8',
        );
      }
    }
  }

  reportSwiftName(dep, spec.swiftName, model);

  // Migration: record a name we derived from the podspec, so the library can
  // drop the podspec. A declared name is already where it belongs, and a name
  // guessed from the npm name would freeze a guess into someone's config.
  const swiftpmName =
    dep.swiftNameSource === 'podspec'
      ? writeSwiftpmName(dep.root, spec.swiftName, {dryRun: ctx.dryRun})
      : undefined;

  return {
    depName,
    status: 'written',
    packageSwiftPath: pkgSwiftPath,
    warnings: spec.warnings,
    previouslyExisted,
    swiftpmName,
  };
}

/**
 * The dependency set the autolinker considers: the iOS entries of
 * autolinking.json plus their transitive SwiftPM dependencies. Null when the
 * file declares none; throws when it cannot be read or parsed. `onSkipped`
 * reports the entries dropped for having no iOS platform.
 */
function collectAutolinkedDeps(
  opts /*: {
    autolinkingJsonPath: string,
    remote: ?{url: string, version: string, identity: string},
    onSkipped?: (name: string) => void,
  } */,
) /*: ?Array<AutolinkedDep> */ {
  const {autolinkingJsonPath, remote, onSkipped} = opts;
  /*:: type AutolinkingJson = {dependencies?: ?{[string]: {root?: string, platforms?: {ios?: ?{...}, ...}, ...}}, ...}; */
  // $FlowFixMe[incompatible-type] JSON.parse returns any
  const data /*: AutolinkingJson */ = JSON.parse(
    fs.readFileSync(autolinkingJsonPath, 'utf8'),
  );
  const deps = data.dependencies;
  if (deps == null) {
    return null;
  }

  const directDeps /*: Array<AutolinkedDep> */ = [];
  for (const name of Object.keys(deps)) {
    const raw = deps[name];
    if (raw == null) continue;
    const root = raw.root;
    const ios = raw.platforms?.ios;
    if (typeof root !== 'string' || ios == null) {
      onSkipped?.(name);
      continue;
    }
    // $FlowFixMe[incompatible-type] `ios` shape is runtime-validated above
    const iosPlatform /*: AutolinkingIosPlatform */ = ios;
    directDeps.push({name, root, platforms: {ios: iosPlatform}});
  }

  try {
    return expandSpmDependencies(directDeps, {
      readConfig: defaultReadConfig,
      resolveDep: defaultResolveDep,
      readPodspec: defaultReadPodspec,
      extraReservedNames: remote != null ? [remote.identity] : undefined,
    });
  } catch (e) {
    if (e instanceof SpmNameCollisionError) {
      throw e;
    }
    // A transitive-resolution failure shouldn't abort the whole pass; fall back
    // to the direct deps so at least those are covered. They are named the way
    // the autolinker names them — a manifest written under any other name
    // outlives this error on disk and then fails to resolve.
    log(`Transitive dependency expansion failed: ${e.message}`);
    return directDeps.map(dep => {
      const resolved = resolveSwiftName(
        dep.name,
        readSwiftpmConfig(dep.root, defaultReadConfig(dep.root)),
        defaultReadPodspec(dep.root, dep.platforms.ios.podspecPath),
      );
      return {
        ...dep,
        swiftName: resolved.name,
        swiftNameSource: resolved.source,
        swiftNamePodspecKey: resolved.podspecKey,
      };
    });
  }
}

// The `.iOS(...)` element of the emitted platforms array — the `.v15` enum form
// pre-v20 scaffolds carry included, and without the array's closing bracket so
// a user-extended array (`[.iOS(…), .macOS(…)]`) is still matched.
const PLATFORM_FLOOR_RE = /platforms: \[\.iOS\((\.v\d+|"[^"]*")\)/;

/**
 * Bring the platform floor of already-scaffolded manifests up to the app's
 * deployment target — `spm add`/`update` must not leave a dep pinned below the
 * app (SwiftPM would refuse to link it), and re-scaffolding is the user's call.
 * Only the platform line of a file carrying our own marker is rewritten; no
 * file is created. `from` is the previous token, verbatim (`15.1` or `.v15`).
 */
function refreshScaffoldedPlatformFloors(
  opts /*: {appRoot: string, autolinkingJsonPath?: string, iosDeploymentTarget: string} */,
) /*: Array<{depName: string, path: string, from: string, to: string}> */ {
  const {appRoot, iosDeploymentTarget} = opts;
  const autolinkingJsonPath =
    opts.autolinkingJsonPath ??
    path.join(appRoot, 'build', 'generated', 'autolinking', 'autolinking.json');
  const refreshed = [];

  // Best-effort: an unreadable autolinking.json, a name collision or a
  // malformed remote config is the autolinker's error to report a moment
  // later, not this pass's.
  let deps /*: ?Array<AutolinkedDep> */ = null;
  try {
    deps = collectAutolinkedDeps({
      autolinkingJsonPath,
      remote: remotePackageConfig(appRoot),
    });
  } catch {
    return refreshed;
  }
  if (deps == null) {
    return refreshed;
  }

  for (const {name: depName, root} of deps) {
    const manifestPath = path.join(root, 'Package.swift');
    let content;
    try {
      content = fs.readFileSync(manifestPath, 'utf8');
    } catch {
      continue;
    }
    if (
      !content.includes(SCAFFOLDER_MARKER) ||
      content.includes(AUTOGEN_MARKER)
    ) {
      continue;
    }
    const match = content.match(PLATFORM_FLOOR_RE);
    if (match == null) {
      continue;
    }
    const from = match[1].replace(/"/g, '');
    if (from === iosDeploymentTarget) {
      continue;
    }
    fs.writeFileSync(
      manifestPath,
      content.replace(match[0], `platforms: [.iOS("${iosDeploymentTarget}")`),
      'utf8',
    );
    refreshed.push({
      depName,
      path: manifestPath,
      from,
      to: iosDeploymentTarget,
    });
  }
  return refreshed;
}

// ---------------------------------------------------------------------------
// Multi-dep orchestrator
// ---------------------------------------------------------------------------

/*::
type ScaffoldAllOptions = {
  appRoot: string,
  projectRoot: string,
  reactNativeRoot: string,
  force?: boolean,
  dryRun?: boolean,
  cacheSlotLabel?: ?string,
  autolinkingJsonPath?: string,
  iosDeploymentTarget?: ?string,
  // npm dep names to skip entirely — used when the user declined the
  // confirmation prompt for first-time scaffolds. Skipped deps still
  // appear in the returned results array with status='skipped-opt-out'.
  skipDeps?: ReadonlyArray<string>,
};
*/

/**
 * Walks autolinking.json, scaffolds each iOS-native dep, returns one
 * ScaffoldResult per dep. Caller (setup-apple-spm.js) prints a structured
 * summary.
 */
function scaffoldAll(
  opts /*: ScaffoldAllOptions */,
) /*: Array<ScaffoldResult> */ {
  const {appRoot, projectRoot, reactNativeRoot} = opts;
  const autolinkingJsonPath =
    opts.autolinkingJsonPath ??
    path.join(appRoot, 'build', 'generated', 'autolinking', 'autolinking.json');

  if (!fs.existsSync(autolinkingJsonPath)) {
    log(
      `autolinking.json not found at ${path.relative(appRoot, autolinkingJsonPath)}; nothing to scaffold.`,
    );
    return [];
  }

  // The scaffolder covers EXACTLY the set the autolinker considers, transitive
  // `spm.dependencies` included. Without them, a transitive native dep that
  // ships no Package.swift would be flagged by the autolinker but never
  // scaffolded here — leaving `react-native spm scaffold` unable to clear the
  // autolinker's missing-manifest error.
  const results /*: Array<ScaffoldResult> */ = [];
  // Outside collectAutolinkedDeps' own try: a malformed remote config
  // (RemoteVersionError) is a misconfiguration to surface, not an expansion
  // failure to degrade past.
  const remote = remotePackageConfig(appRoot);
  const allDeps = collectAutolinkedDeps({
    autolinkingJsonPath,
    remote,
    onSkipped: name => {
      results.push({
        depName: name,
        status: 'skipped-no-ios',
        reason: 'no iOS platform in autolinking.json',
      });
    },
  });
  if (allDeps == null) {
    return results;
  }

  // Index every autolinked dep's podspec name → its npm name, so a dep that
  // depends on a sibling by its pod name (reanimated's `s.dependency
  // "RNWorklets"`) can be wired to the sibling's package (react-native-worklets).
  // The podspec file basename is the pod name for RN-ecosystem libs (and is
  // cheap — no `pod ipc` pre-pass).
  const podToNpm /*: Map<string, string> */ = new Map();
  for (const dep of allDeps) {
    const podspecPath = dep.platforms?.ios?.podspecPath;
    if (typeof podspecPath === 'string' && podspecPath.length > 0) {
      podToNpm.set(path.basename(podspecPath, '.podspec'), dep.name);
    } else {
      // Transitive entries synthesized by expandSpmDependencies (declared via
      // `spm.dependencies` in react-native.config.js) carry no podspecPath —
      // discover the podspec at the dep root so podspec-name sibling deps
      // (e.g. `s.dependency "TestLibraryCommon"`) still wire to their npm
      // package.
      for (const found of findPodspecs(dep.root)) {
        podToNpm.set(path.basename(found, '.podspec'), dep.name);
      }
    }
  }

  const swiftNameByNpm /*: Map<string, string> */ = new Map();
  for (const dep of allDeps) {
    if (dep.swiftName != null) {
      swiftNameByNpm.set(dep.name, dep.swiftName);
    }
  }

  const ctx /*: ScaffoldContext */ = {
    appRoot,
    projectRoot,
    reactNativeRoot,
    force: opts.force === true,
    dryRun: opts.dryRun === true,
    cacheSlotLabel: opts.cacheSlotLabel ?? null,
    iosDeploymentTarget: opts.iosDeploymentTarget ?? null,
    podToNpm,
    swiftNameByNpm,
    remote,
  };
  const skipSet /*: Set<string> */ = new Set(opts.skipDeps ?? []);

  for (const dep of allDeps) {
    if (skipSet.has(dep.name)) {
      results.push({
        depName: dep.name,
        status: 'skipped-opt-out',
        reason: 'User declined scaffolding for this dep.',
      });
      continue;
    }
    try {
      results.push(scaffoldPackageSwiftForDep(dep, ctx));
    } catch (e) {
      results.push({depName: dep.name, status: 'error', reason: e.message});
    }
  }
  return results;
}

module.exports = {
  refreshScaffoldedPlatformFloors,
  scaffoldAll,
  scaffoldPackageSwiftForDep,
  translatePodspecToSpmTarget,
  emitScaffoldedPackageSwift,
  SCAFFOLDER_MARKER,
  SCAFFOLDER_VERSION,
};
